const normalized = code => String(code || "en").toLowerCase().split("-")[0];
export function labels(code) {
  const row = copy[normalized(code)] || copy.en;
  return {...Object.fromEntries(keys.map((key, index) => [key, row[index]])), ...(localeFeatures[normalized(code)] || localeFeatures.en)};
}

