const sourceOptionColors = "黑色 白色 红色 蓝色 绿色 黄色 粉色 紫色 棕色 灰色 米色 橙色".split(" ");
const sourceEnglishColors = "black white red blue green yellow pink purple brown grey beige orange".split(" ");
for(const [code, names] of Object.entries(optionColorNames)) {const words=titleGlossary[code] ||= {}; names.split("|").forEach((color,i)=>{words[sourceEnglishColors[i]]=color});}
const titleRegex = new Map();
const quotePattern = text => text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const cleanName = name => String(name || '').replace(/#[^\s#]+/g,'').replace(/\s+/g,' ').trim();
export function title(code, name) {
  const locale = normalized(code);
  const words = titleGlossary[locale];
  const colors = (optionColorNames[locale] || optionColorNames.en).split("|");
  const clean = cleanName(name).replace(/黑色|白色|红色|蓝色|绿色|黄色|粉色|紫色|棕色|灰色|米色|橙色/g, c=>colors[sourceOptionColors.indexOf(c)]);
  if(locale==="en") return clean;
  if (!words) return clean;
  if (!titleRegex.has(locale)) {
    const keys = Object.keys(words).sort((a,b)=>b.length-a.length).map(quotePattern);
    titleRegex.set(locale,new RegExp('(?<![\\p{L}\\p{N}_])(?:'+keys.join('|')+')(?![\\p{L}\\p{N}_])','giu'));
  }
  const protectedParts = [];
  const masked = clean.replace(protectedNames, brand => {
    protectedParts.push(brand);
    return '\uE000'+(protectedParts.length-1)+'\uE001';
  });
  const translatedTerms=[];
  const pattern=titleRegex.get(locale);
  const display=masked.replace(pattern, term=>{
    const localized=words[term.toLowerCase()] || term;
    translatedTerms.push(localized);
    return localized;
  }).replace(/\uE000(\d+)\uE001/g, (_,index)=>protectedParts[index]);
  const residue=masked.replace(pattern,' ').replace(/\uE000\d+\uE001/g,' ')
    .replace(/\b(?:the|a|of|for|with|and|in|x)\b/gi,' ')
    .replace(/\b(?:[A-Z0-9]*[0-9][A-Za-z0-9.-]*|[A-Z]{2,6})\b/g,' ');
  // Keep identity, distinguishing model numbers and localized attributes in compact labels
  // when a longer seller description cannot be localized fluently by the glossary.
  if(protectedParts.length && translatedTerms.length && (residue.match(/[a-zA-Z]{3,}/g)||[]).length>1) {
    const model=masked.match(/\b(?=[A-Za-z0-9.-]*[a-zA-Z])(?=[A-Za-z0-9.-]*\d)[A-Za-z0-9.-]{2,}\b/g)||[];
    const count=clean.match(/[（(\[]\s*(\d+)\s*(?:styles?|models?|colou?rs?)\s*[）)\]]/i);
    const noun=count?.[0].match(/styles?|models?|colou?rs?/i)?.[0].toLowerCase();
    const optionLabel=noun ? (words[noun] || words[noun+'s']) : '';
    const attributes=translatedTerms.filter((word,index)=>word!==optionLabel&&translatedTerms.indexOf(word)===index);
    if(attributes.length) return [[...new Set([...protectedParts,...model])].join(' '),attributes.join(' · '),count&&optionLabel?'('+count[1]+' '+optionLabel+')':''].filter(Boolean).join(' ');
  }
  return display.replace(/（/g,' (').replace(/）/g,')').replace(/\s+/g,' ').trim();
}

export async function translateTitles(locale,names) {
  return names.map(name=>title(locale,name));
}

// Use a locally installed browser language model for full phrases, including new seller wording.
// The glossary stays visible on devices without a ready model.
export function titleTranslationClient() {
  return '('+String(async function enhanceProductTitles(){
    const targetLanguage = document.documentElement.lang;
    const nodes = document.querySelectorAll('[data-source-title]');
    if(!nodes.length || !('Translator' in self)) return;
    const names = new Map();
    for(const node of nodes) {
      const name = node.dataset.sourceTitle?.trim();
      if(!name) continue;
      if(!names.has(name)) names.set(name,[]);
      names.get(name).push(node);
    }
    const models = new Map();
    try {
      for(const [original,elements] of names) {
        const sourceLanguage = /[\u4e00-\u9fff]/.test(original) ? 'zh' : 'en';
        if(sourceLanguage===targetLanguage || !original.match(/[\p{L}]{2}/u)) continue;
        if(!models.has(sourceLanguage)) {
          const options={sourceLanguage,targetLanguage};
          if(await Translator.availability(options)!=='available') {
            models.set(sourceLanguage,null);
          } else {
            models.set(sourceLanguage,await Translator.create(options));
          }
        }
        const translator=models.get(sourceLanguage);
        if(!translator) continue;
        const output=await translator.translate(original);
        if(!output?.trim()) continue;
        for(const element of elements) element.textContent=output.trim();
      }
    } catch {} finally {
      for(const model of models.values()) model?.destroy();
    }
  })+')();';
}

